"""Read-only manifest of completed dev-only Slurm episode records."""
import sys,json,hashlib,collections,math,statistics
from pathlib import Path
p=Path(sys.argv[1]);assert (p/'DONE').exists(), 'not complete'
prov=json.loads((p/'provenance.json').read_text());seeds=list(range(1001,1031));assert prov['seeds']==seeds
bounds=json.loads((Path(__file__).parent/'endpoint_bounds.json').read_text())
zone_rows=bounds['before' if prov['head'].startswith('d337') else 'after']
expected={(n,a,s) for n in prov['scenarios'] for a in prov['planners'] for s in seeds}
summary=[json.loads(l) for l in (p/'summary.jsonl').read_text().splitlines()];assert len(summary)==270
cells=[]
for n,a,s,reason,steps,sha in summary:
 f=p/f'{n}__{a}__{s}.json';b=f.read_bytes();assert hashlib.sha256(b).hexdigest()==sha
 d=json.loads(b);assert (n,a,s)==(d['scenario_id'],d['algo'],d['seed']);assert d['git_hash']==prov['head'];assert 1001<=s<=1030
 e=d['event_ledger']['exact_events'];st=d['algorithm_metadata']['simulation_step_trace']['steps']
 c={'scenario':n,'planner':a,'seed':s,'termination_reason':reason,'steps':steps,'horizon':d['horizon'],'events':e,'raw_sha256':sha,'raw_path':str(f),'config_hash':d['config_hash'],'runtime_input_records':d['runtime_input_records'],'pedestrian_count':len(st[0]['pedestrians']),'min_center_distance_m':d['metrics'].get('min_distance'),'integrity_contradictions':d['integrity']['contradictions'],'reset_overlap':d['spawn_validity']['reset_overlap'],'status':d['status'],'collision_counts':{k:d['metrics'].get(k) for k in ['collisions','ped_collision_count','obstacle_collision_count','total_collision_count']},'interaction_exposure':d['interaction_exposure']}
 c['algorithm_execution']={k:d['algorithm_metadata'].get(k) for k in ['algorithm','status','config_hash','policy_semantics','planner_kinematics','planner_runtime']}
 reset=d['algorithm_metadata']['simulation_step_trace']['reset']
 c['reset_robot_position']=reset['robot']['position']
 c['endpoint_occupancy_at_reset']=[]
 for zone in (z for z in zone_rows if z['scenario']==n):
  xmin,ymin,xmax,ymax=zone['bounds']
  distances=[math.hypot(max(xmin-q['position'][0],0,q['position'][0]-xmax),max(ymin-q['position'][1],0,q['position'][1]-ymax)) for q in reset['pedestrians']]
  c['endpoint_occupancy_at_reset'].append({'zone':zone['zone'],'radius_m':zone['ped_radius_m'],'count':sum(x<=zone['ped_radius_m'] for x in distances),'min_rectangle_to_pedestrian_center_m':min(distances),'distance_convention':'robot_zone_to_nominal_pedestrian_centres'})
 if n=='francis2023_pedestrian_overtaking':
  c['reset_pedestrian_position']=reset['pedestrians'][0]['position']
  c['starts_behind_reset']=c['reset_pedestrian_position'][0]<c['reset_robot_position'][0]
  dx=[q['pedestrians'][0]['position'][0]-q['robot']['position'][0] for q in st];ys=[q['pedestrians'][0]['position'][1] for q in st]
  c['overtaking']={'starts_behind_first_step':dx[0]<0,'first_step_robot':st[0]['robot']['position'],'first_step_pedestrian':st[0]['pedestrians'][0]['position'],'crosses_from_behind':dx[0]<0 and max(dx)>0,'first_crossing_step':next((q['step'] for q,x in zip(st,dx) if x>0),None),'lateral_excursion_m':max(ys)-min(ys),'risk_near_field_steps':sum(math.dist(q['pedestrians'][0]['position'],q['robot']['position'])<=2.5 for q in st)}
 cells.append(c)
assert {(c['scenario'],c['planner'],c['seed']) for c in cells}==expected
aggregates=[]
for n in prov['scenarios']:
 for a in prov['planners']:
  cs=[c for c in cells if c['scenario']==n and c['planner']==a];assert len(cs)==30
  row={'scenario':n,'planner':a,'n':30,'success':sum(c['events']['goal_reached'] for c in cs),'collision':sum(c['events']['collision'] for c in cs),'early_collision_le_20':sum(c['events']['collision'] and c['steps']<=20 for c in cs),'timeout':sum(c['events']['timeout'] for c in cs),'invalid_run':sum(c['events']['invalid_run'] for c in cs),'pedestrian_counts':sorted(set(c['pedestrian_count'] for c in cs)),'reset_overlap':sum(c['reset_overlap'] for c in cs),'integrity_contradictions':sum(len(c['integrity_contradictions']) for c in cs)}
  row['algorithm_statuses']=dict(collections.Counter(c['algorithm_execution']['status'] for c in cs))
  row['endpoint_occupancy_at_reset']={kind:{'episodes_with_pedestrians':sum(any(z['zone'].startswith(kind) and z['count']>0 for z in c['endpoint_occupancy_at_reset']) for c in cs),'pedestrian_occurrences':sum(z['count'] for c in cs for z in c['endpoint_occupancy_at_reset'] if z['zone'].startswith(kind))} for kind in ['spawn','goal']}
  if n=='francis2023_pedestrian_overtaking':row['overtaking']={'starts_behind':sum(c['overtaking']['starts_behind_first_step'] for c in cs),'crosses_from_behind':sum(c['overtaking']['crosses_from_behind'] for c in cs),'collision_free_crossings':sum(c['overtaking']['crosses_from_behind'] and not c['events']['collision'] for c in cs),'min_center_distance_m':min(c['min_center_distance_m'] for c in cs),'median_lateral_excursion_m':statistics.median(c['overtaking']['lateral_excursion_m'] for c in cs),'risk_near_field_steps':sum(c['overtaking']['risk_near_field_steps'] for c in cs)}
  aggregates.append(row)
result={'provenance':prov,'aggregates':aggregates,'cells':cells,'raw_root':str(p),'done':(p/'DONE').read_text()};Path(sys.argv[2]).write_text(json.dumps(result,indent=2));print(json.dumps(aggregates,indent=2))
